1480	static void ribbon_offset_vertex(const vmap_point_t * pts, int32_t n, int32_t i,
1481	    double hw, double * lx, double * ly, double * rx, double * ry)
1482	{
1483	    double n0x;
1484	    double n0y;
1485	    double n1x;
1486	    double n1y;
1487	    double mx;
1488	    double my;
1489	    double mlen;
1490	
1491	    if (i == 0) {
1492	        const double dx = (double)(pts[1].x - pts[0].x);
1493	        const double dy = (double)(pts[1].y - pts[0].y);
1494	        const double len = hypot(dx, dy);
1495	
1496	        if (len < 1e-6) {
1497	            n0x = 0.0;
1498	            n0y = 1.0;
1499	        } else {
1500	            n0x = -dy / len;
1501	            n0y = dx / len;
1502	        }
1503	        mx = n0x;
1504	        my = n0y;
1505	        mlen = hw;
1506	    } else if (i == n - 1) {
1507	        const double dx = (double)(pts[n - 1].x - pts[n - 2].x);
1508	        const double dy = (double)(pts[n - 1].y - pts[n - 2].y);
1509	        const double len = hypot(dx, dy);
1510	
1511	        if (len < 1e-6) {
1512	            n0x = 0.0;
1513	            n0y = 1.0;
1514	        } else {
1515	            n0x = -dy / len;
1516	            n0y = dx / len;
1517	        }
1518	        mx = n0x;
1519	        my = n0y;
1520	        mlen = hw;
1521	    } else {
1522	        const double dx0 = (double)(pts[i].x - pts[i - 1].x);
1523	        const double dy0 = (double)(pts[i].y - pts[i - 1].y);
1524	        const double dx1 = (double)(pts[i + 1].x - pts[i].x);
1525	        const double dy1 = (double)(pts[i + 1].y - pts[i].y);
1526	        const double len0 = hypot(dx0, dy0);
1527	        const double len1 = hypot(dx1, dy1);
1528	        double dot;
1529	
1530	        if (len0 < 1e-6 || len1 < 1e-6) {
1531	            mx = 0.0;
1532	            my = 1.0;
1533	            mlen = hw;
1534	            goto out;
1535	        }
1536	
1537	        n0x = -dy0 / len0;
1538	        n0y = dx0 / len0;
1539	        n1x = -dy1 / len1;
1540	        n1y = dx1 / len1;
1541	        mx = n0x + n1x;
1542	        my = n0y + n1y;
1543	        mlen = hypot(mx, my);
1544	        if (mlen < 1e-6) {
1545	            mx = n0x;
1546	            my = n0y;
1547	            mlen = hw;
1548	            goto out;
1549	        }
1550	
1551	        dot = (mx / mlen) * n0x + (my / mlen) * n0y;
1552	        mx /= mlen;
1553	        my /= mlen;
1554	        if (fabs(dot) > 1e-4) {
1555	            mlen = hw / dot;
1556	            if (mlen > hw * 2.5) {
1557	                mlen = hw * 2.5;
1558	            } else if (mlen < -hw * 2.5) {
1559	                mlen = -hw * 2.5;
1560	            }
1561	        } else {
1562	            mlen = hw;
1563	        }
1564	    }
1565	
1566	out:
1567	    *lx = (double)pts[i].x + mx * mlen;
1568	    *ly = (double)pts[i].y + my * mlen;
1569	    *rx = (double)pts[i].x - mx * mlen;
1570	    *ry = (double)pts[i].y - my * mlen;
1571	}
