1625	void vmap_render_stroke_ribbon(vmap_canvas_t * c, const vmap_point_t * pts,
1626	    int32_t n, int32_t width, uint16_t color)
1627	{
1628	#if VMAP_RENDER_AA
1629	    int32_t start;
1630	
1631	    if (!c || !pts || n < 2 || width < 1) {
1632	        return;
1633	    }
1634	
1635	    if (n <= VMAP_RIBBON_CHUNK_MAX) {
1636	        stroke_ribbon_aa_chunk(c, pts, n, width, color, true, true);
1637	        return;
1638	    }
1639	
1640	    start = 0;
1641	    while (start < n - 1) {
1642	        int32_t end = start + VMAP_RIBBON_CHUNK_MAX - 1;
1643	        bool cap_start;
1644	        bool cap_end;
1645	
1646	        if (end >= n - 1) {
1647	            end = n - 1;
1648	        }
1649	
