1651	        cap_end = (end == n - 1);
1652	        stroke_ribbon_aa_chunk(c, pts + start, end - start + 1, width, color,
1653	            cap_start, cap_end);
1654	
1655	        if (end >= n - 1) {
1656	            break;
1657	        }
1658	
1659	        start = end;
1660	    }
1661	#else
