1852	    /* 早退：点已经是画布坐标，包围盒几乎免费。 */
1853	    {
1854	        int32_t bx1 = pts[0].x;
1855	        int32_t by1 = pts[0].y;
1856	        int32_t bx2 = pts[0].x;
1857	        int32_t by2 = pts[0].y;
1858	
1859	        for (i = 1; i < n; i++) {
1860	            if (pts[i].x < bx1) { bx1 = pts[i].x; }
1861	            if (pts[i].x > bx2) { bx2 = pts[i].x; }
1862	            if (pts[i].y < by1) { by1 = pts[i].y; }
1863	            if (pts[i].y > by2) { by2 = pts[i].y; }
1864	        }
1865	        if (!box_may_write(c, bx1 - join_r - 2, by1 - join_r - 2,
1866	                bx2 + join_r + 2, by2 + join_r + 2)) {
1867	            return;
