1878	/* ── 线宽阶梯（docs/map/STYLE.md §3）────────────────────────────────────
1879	 *
1880	 * 设备 1× 基准是 z14；`style->road[cls].w` 存的是 1/10 设备像素。
1881	 * `width = base × 2^((z-14)/2)`，夹在 0.62 ~ 2.4；而板端的线性倍率就是瓦片
1882	 * scale（z14 = 1×，zoom 每升一级线性翻倍）⇒ 倍率 = sqrt(scale)，与 HTML
1883	 * `vmapZoomWidthScale()` 是同一条曲线。每个瓦片算一次，不是每像素。
1884	 */
1885	
1886	/** @brief 线宽倍率（Q8 定点，256 = 1.0），夹在 0.62 ~ 2.4。 */
1887	static int32_t road_width_scale_q8(float scale)
1888	{
1889	    double ws;
1890	
1891	    if (!(scale > 0.0f)) {
1892	        return 256;
1893	    }
1894	
1895	    ws = sqrt((double)scale);
1896	    if (ws < 0.62) {
1897	        ws = 0.62;
1898	    } else if (ws > 2.4) {
1899	        ws = 2.4;
1900	    }
1901	
1902	    return (int32_t)lround(ws * 256.0);
1903	}
