1905	/** @brief 芯宽：表值（1/10 px）× 倍率 ⇒ 设备像素（四舍五入，最小 1）。 */
1906	static int32_t road_core_px(int32_t w10, int32_t ws_q8)
1907	{
1908	    const int32_t px = (w10 * ws_q8 + 1280) / 2560;   /* w10/10 × ws_q8/256 */
1909	
1910	    return px < 1 ? 1 : px;
1911	}
1912	
1913	/** @brief 壳宽 = 芯 + `max(1.1, 1.9 × min(1.7, ws))`（HTML `caseExtra` 同一式）。 */
1914	static int32_t road_case_px(int32_t core_px, int32_t ws_q8)
1915	{
1916	    int32_t ws10 = (ws_q8 * 10 + 128) >> 8;
1917	    int32_t extra;
1918	
1919	    if (ws10 < 1) {
1920	        ws10 = 1;
1921	    } else if (ws10 > 17) {
1922	        ws10 = 17;                        /* min(1.7, ws)：ws10 单位 1/10，1.7 ⇒ 17 */
1923	    }
1924	    extra = 19 * ws10;                    /* 1.9 × ws，单位 1/100 px */
1925	    if (extra < 110) {
1926	        extra = 110;                      /* max(1.1, …) */
1927	    }
1928	
1929	    return core_px + (extra + 50) / 100;
1930	}
