1932	/**
1933	 * @brief 沿折线按**弧长**切虚线（实 on / 虚 off，设备像素）。
1934	 *
1935	 * 不能按 1px 递进：那样每一小段都被线宽撑成圆点/锯齿（STYLE.md §5.2）。
1936	 * 这里照 `lvgl_sim/src/scene_vmap.c` 的 `dashed_line()`：按"当前相位还剩多少"
1937	 * 整段推进，相位跨线段连续。
1938	 */
1939	static void draw_dashed_polyline(vmap_canvas_t * c, const vmap_point_t * pts,
1940	    int32_t n, int32_t width, uint16_t color, int32_t on, int32_t off)
1941	{
1942	    const int32_t period = on + off;
1943	    int32_t phase = 0;
1944	    int32_t i;
1945	
1946	    if (!c || !pts || n < 2 || width < 1 || on <= 0 || off <= 0) {
1947	        return;
1948	    }
1949	
1950	    for (i = 0; i + 1 < n; i++) {
1951	        const int32_t ax = pts[i].x;
1952	        const int32_t ay = pts[i].y;
1953	        const int32_t dx = pts[i + 1].x - ax;
1954	        const int32_t dy = pts[i + 1].y - ay;
1955	        const int64_t len2 = (int64_t)dx * dx + (int64_t)dy * dy;
1956	        const int32_t len = (int32_t)(sqrt((double)len2) + 0.5);
1957	        int32_t t = 0;
1958	
1959	        if (len < 1) {
1960	            continue;
1961	        }
1962	
1963	        while (t < len) {
1964	            const int32_t in_phase = phase % period;
1965	            const bool in_dash = in_phase < on;
1966	            const int32_t left = in_dash ? (on - in_phase) : (period - in_phase);
1967	            int32_t step = left;
1968	
1969	            if (step > len - t) {
1970	                step = len - t;
1971	            }
1972	            if (step <= 0) {
1973	                break;
1974	            }
1975	            if (in_dash) {
1976	                const int32_t x0 = ax + (int32_t)((int64_t)dx * t / len);
1977	                const int32_t y0 = ay + (int32_t)((int64_t)dy * t / len);
1978	                const int32_t x1 = ax + (int32_t)((int64_t)dx * (t + step) / len);
1979	                const int32_t y1 = ay + (int32_t)((int64_t)dy * (t + step) / len);
1980	
1981	                vmap_render_draw_thick_line(c, x0, y0, x1, y1, width, color);
1982	            }
1983	            t += step;
1984	            phase += step;
1985	        }
1986	    }
1987	}
