1989	static void draw_road_feature_line(vmap_canvas_t * c, const vmap_feature_t * f,
1990	    float base_x, float base_y, float u, int32_t width, uint16_t color,
1991	    int32_t dash_on, int32_t dash_off, vmap_point_t * scratch, int scratch_cap)
1992	{
1993	    int32_t n;
1994	    int32_t i;
1995	
1996	    if (!f || f->point_count < 2 || width < 1 || !scratch || scratch_cap < 2) {
1997	        return;
1998	    }
1999	
2000	    n = f->point_count;
2001	    if (n > scratch_cap) {
2002	        n = scratch_cap;
2003	    }
2004	
2005	    for (i = 0; i < n; i++) {
2006	        scratch[i].x = (int32_t)lroundf(base_x + vmap_feature_x(f, (uint16_t)i) * u);
2007	        scratch[i].y = (int32_t)lroundf(base_y + vmap_feature_y(f, (uint16_t)i) * u);
2008	    }
2009	
2010	    /* 早退：完全写不到就不必简化、不必描边、不必点圆盘。外扩 = 描边半宽 + AA 余量
2011	     * （保守方向），且必须在 VMAP_ROAD_SIMPLIFY 之前 —— 那一步也是纯浪费。 */
2012	    {
2013	        const int32_t pad = (width + 1) / 2 + 2;
2014	        int32_t bx1 = scratch[0].x;
2015	        int32_t by1 = scratch[0].y;
2016	        int32_t bx2 = scratch[0].x;
2017	        int32_t by2 = scratch[0].y;
2018	
2019	        for (i = 1; i < n; i++) {
2020	            if (scratch[i].x < bx1) { bx1 = scratch[i].x; }
2021	            if (scratch[i].x > bx2) { bx2 = scratch[i].x; }
2022	            if (scratch[i].y < by1) { by1 = scratch[i].y; }
2023	            if (scratch[i].y > by2) { by2 = scratch[i].y; }
2024	        }
2025	        if (!box_may_write(c, bx1 - pad, by1 - pad, bx2 + pad, by2 + pad)) {
2026	            return;
2027	        }
2028	    }
2029	
2030	#if VMAP_ROAD_SIMPLIFY
2031	    n = simplify_road_polyline(scratch, n, VMAP_ROAD_MIN_SEG_PX,
2032	        VMAP_ROAD_MAX_DEV_PX);
2033	    if (n >= 4) {
2034	        n = simplify_road_polyline(scratch, n, VMAP_ROAD_MIN_SEG_PX,
2035	            VMAP_ROAD_MAX_DEV_PX);
2036	    }
2037	#endif
2038	
2039	    /* 面状 highway 残渣（宽环）不画，虚线也一样跳过。 */
2040	    if (road_ring_is_area(scratch, n)) {
2041	        return;
2042	    }
2043	
2044	    if (dash_on > 0 && dash_off > 0) {
2045	        draw_dashed_polyline(c, scratch, n, width, color, dash_on, dash_off);
2046	    } else {
2047	        draw_road_polyline(c, scratch, n, width, color);
2048	    }
2049	}
