579	static uint16_t mix_rgb565(uint16_t bg, uint16_t fg, uint8_t mix)
580	{
581	    uint32_t mix5;
582	    uint32_t bg32;
583	    uint32_t fg32;
584	    uint32_t r;
585	    uint32_t g;
586	    uint32_t b;
587	
588	    if (mix >= 255) {
589	        return fg;
590	    }
591	    if (mix == 0) {
592	        return bg;
593	    }
594	
595	    mix5 = ((uint32_t)mix + 4U) >> 3;
596	    bg32 = bg;
597	    fg32 = fg;
598	    r = ((bg32 & 0xF800U) + (((fg32 & 0xF800U) - (bg32 & 0xF800U)) * mix5 >> 5))
599	        & 0xF800U;
600	    g = ((bg32 & 0x07E0U) + (((fg32 & 0x07E0U) - (bg32 & 0x07E0U)) * mix5 >> 5))
601	        & 0x07E0U;
602	    b = ((bg32 & 0x001FU) + (((fg32 & 0x001FU) - (bg32 & 0x001FU)) * mix5 >> 5))
603	        & 0x001FU;
604	    return (uint16_t)(r | g | b);
605	}
