640	/** @brief 单像素混合（边界与裁剪已在调用方处理完毕）。 */
641	static inline void blend_row_pixel(uint16_t * row, int32_t x, uint16_t color,
642	    uint8_t alpha)
643	{
644	    if (alpha == 0u) {
645	        return;
646	    }
647	    if (alpha >= 255u) {
648	        row[x] = color;
649	        STAT_STORE(2);
650	        return;
651	    }
652	    row[x] = mix_rgb565(row[x], color, alpha);
653	    STAT_STORE(2);
654	}
