656	/** @brief 对 [x0,x1] 内的像素按覆盖度落笔（覆盖 <=0 的自动跳过）。 */
657	static void cover_partial_px(uint16_t * row, int32_t x0, int32_t x1,
658	    int32_t x0_fp, int32_t x1_fp, uint16_t color)
659	{
660	    int32_t x;
661	
662	    for (x = x0; x <= x1; x++) {
663	        const int32_t px0_fp = x << VMAP_FP_SHIFT;
664	        const int32_t px1_fp = px0_fp + VMAP_FP_ONE;
665	        const int32_t a_fp = x0_fp > px0_fp ? x0_fp : px0_fp;
666	        const int32_t b_fp = x1_fp < px1_fp ? x1_fp : px1_fp;
667	        const int32_t cov_fp = b_fp - a_fp;
668	
669	        if (cov_fp <= 0) {
670	            continue;
671	        }
672	        if (cov_fp >= VMAP_FP_ONE) {
673	            row[x] = color;
674	            STAT_STORE(2);
675	            continue;
676	        }
677	        blend_row_pixel(row, x, color,
678	            (uint8_t)(((uint32_t)cov_fp * 255U) >> VMAP_FP_SHIFT));
679	    }
680	}
