682	static void blend_pixel(vmap_canvas_t * c, int32_t x, int32_t y, uint16_t color,
683	    uint8_t alpha)
684	{
685	    uint16_t * row;
686	
687	    if (!c || !c->buf || alpha == 0) {
688	        return;
689	    }
690	    if ((uint32_t)x >= (uint32_t)c->w || (uint32_t)y >= (uint32_t)c->h) {
691	        return;
692	    }
693	    if (!canvas_in_clip(c, x, y)) {
694	        return;
695	    }
696	    if (alpha >= 255) {
697	        put_pixel(c, x, y, color);
698	        return;
699	    }
700	
701	    row = (uint16_t *)((uint8_t *)c->buf + (size_t)y * c->stride);
702	    row[x] = mix_rgb565(row[x], color, alpha);
703	}
