static int32_t ribbon_arc_emit(vmap_fp_point_t * poly, int32_t pn, int32_t cap,
    double cx, double cy, double hw,
    double ax, double ay, double bx, double by, int32_t levels)
{
    double mx;
    double my;
    double len;

    if (levels <= 0 || pn >= cap) {
        return pn;
    }

    mx = ax + bx;
    my = ay + by;
    len = hypot(mx, my);
    if (len < 1e-6) {
        return pn;
    }
    mx /= len;
    my /= len;

    pn = ribbon_arc_emit(poly, pn, cap, cx, cy, hw, ax, ay, mx, my, levels - 1);
    if (pn < cap) {
        poly[pn].x = (int32_t)lround((cx + mx * hw) * (double)VMAP_FP_ONE);
        poly[pn].y = (int32_t)lround((cy + my * hw) * (double)VMAP_FP_ONE);
        pn++;
    }
    return ribbon_arc_emit(poly, pn, cap, cx, cy, hw, mx, my, bx, by, levels - 1);
}
