{"file_path": "/tmp/rd1/ribbon_test.c", "content": "/* 合成几何检验：多边形丝带不能鼓包/不能有洞。
 * 用法：ribbon_test <outdir>
 * 画布黑底白线，阈值 50% 覆盖后统计 (a) 亮像素到折线的最大距离，
 * (b) 折线附近应有的像素里有多少没被画到（洞）。 */
#include "vmap_render.h"

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define W 160
#define H 160

static uint16_t buf[W * H];

static void dump_ppm(const char * path)
{
    FILE * f = fopen(path, "wb");
    int i;

    fprintf(f, "P6\n%d %d\n255\n", W, H);
    for (i = 0; i < W * H; i++) {
        const uint16_t v = buf[i];
        const unsigned char rgb[3] = {
            (unsigned char)(((v >> 11) & 0x1f) * 255 / 31),
            (unsigned char)(((v >> 5) & 0x3f) * 255 / 63),
            (unsigned char)((v & 0x1f) * 255 / 31)
        };
        fwrite(rgb, 1, 3, f);
    }
    fclose(f);
}

/* 点到折线的最短距离 */
static double dist_pl(const vmap_point_t * pts, int n, double px, double py)
{
    double best = 1e9;
    int i;

    for (i = 0; i + 1 < n; i++) {
        const double ax = pts[i].x;
        const double ay = pts[i].y;
        const double bx = pts[i + 1].x;
        const double by = pts[i + 1].y;
        const double dx = bx - ax;
        const double dy = by - ay;
        const double l2 = dx * dx + dy * dy;
        double t;
        double qx;
        double qy;
        double d;

        if (l2 < 1e-9) {
            qx = ax;
            qy = ay;
        } else {
            t = ((px - ax) * dx + (py - ay) * dy) / l2;
            if (t < 0.0) { t = 0.0; }
            if (t > 1.0) { t = 1.0; }
            qx = ax + t * dx;
            qy = ay + t * dy;
        }
        d = hypot(px - qx, py - qy);
        if (d < best) { best = d; }
    }
    return best;
}

static int run_case(const char * name, const vmap_point_t * pts, int n,
    int width, const char * outdir)
{
    vmap_canvas_t c;
    double hw = width * 0.5;
    double dmax = 0.0;
    int holes = 0;
    int lit = 0;
    int x;
    int y;
    char path[512];

    memset(buf, 0, sizeof(buf));
    memset(&c, 0, sizeof(c));
    c.buf = buf;
    c.w = W;
    c.h = H;
    c.stride = W * 2;

    vmap_render_stroke_ribbon(&c, pts, n, width, 0xffffu);

    for (y = 0; y < H; y++) {
        for (x = 0; x < W; x++) {
            const uint16_t v = buf[y * W + x];
            const double px = x + 0.5;
            const double py = y + 0.5;
            const double d = dist_pl(pts, n, px, py);

            if (v >= 0x8000u) {
                lit++;
                if (d > dmax) { dmax = d; }
            }
        }
    }
    /* 洞：像素中心在丝带内部（距离 < hw-0.5，必然整像素覆盖）却没画 */
    for (y = 1; y < H - 1; y++) {
        for (x = 1; x < W - 1; x++) {
            const double d = dist_pl(pts, n, x + 0.5, y + 0.5);

            if (d < hw - 0.5 && buf[y * W + x] < 0x4000u) {
                holes++;
            }
        }
    }

    snprintf(path, sizeof(path), "%s/%s.ppm", outdir, name);
    dump_ppm(path);
    printf("%-12s n=%2d w=%d  lit=%5d  dmax=%.2f (hw=%.1f)  holes=%d\n",
        name, n, width, lit, dmax, hw, holes);
    return (holed_ok: (dmax <= hw + 0.75) && holes == 0) ? 0 : 1;
}

int main(int argc, char ** argv)
{
    const char * outdir = argc > 1 ? argv[1] : ".";
    int bad = 0;

    {
        const vmap_point_t p[] = {{10, 80}, {40, 80}, {70, 60}, {100, 100},
            {130, 100}, {150, 60}};

        bad += run_case("zigzag", p, (int)(sizeof(p) / sizeof(p[0])), 3, outdir);
    }
    {
        const vmap_point_t p[] = {{20, 20}, {80, 80}, {60, 120}};

        bad += run_case("sharp", p, 3, 5, outdir);
    }
    {
        const vmap_point_t p[] = {{20, 120}, {80, 40}, {140, 120}};  /* 90° V */

        bad += run_case("vee90", p, 3, 4, outdir);
    }
    {
        const vmap_point_t p[] = {{10, 30}, {60, 30}, {60, 90}, {120, 90}};

        bad += run_case("right", p, 4, 2, outdir);
    }
    {
        const vmap_point_t p[] = {{10, 150}, {40, 150}};

        bad += run_case("dash", p, 2, 3, outdir);
    }
    {
        /* 80 点细锯齿，跨分块（>64）：接缝不能断 */
        vmap_point_t p[80];
        int i;

        for (i = 0; i < 80; i++) {
            p[i].x = 10 + i;
            p[i].y = 40 + (i & 1) * 2;
        }
        bad += run_case("chunk", p, 80, 2, outdir);
    }

    printf("bad=%d\n", bad);
    return bad;
}
"}

