     * Q15 后与 cos/sin 表组合，不再有 double 逐点运算（板端 double 是软浮点）。 */
    const int32_t cx_fp = cx << VMAP_FP_SHIFT;
    const int32_t cy_fp = cy << VMAP_FP_SHIFT;
    const int32_t r_fp = (int32_t)lround(hw * (double)VMAP_FP_ONE);
    const int32_t ux15 = (int32_t)lround(ux * 32768.0);
    const int32_t uy15 = (int32_t)lround(uy * 32768.0);
    const int32_t step = 16 / segs;
    int32_t k;

    for (k = step; k < 16; k += step) {
        const int64_t c = s_ribbon_cos16[k];
        const int64_t s = s_ribbon_sin16[k];
        /* rot(u,-90°) = (uy,-ux)：点 = c·u + s·rot(u,-90°) */
        const int32_t ox = (int32_t)((c * ux15 + s * uy15) >> 15);
