{"content": "/* 对照基准：按一屏地图的规模重复描边，比较旧实现（逐顶点圆盘）与新实现。
 * 只比较相对量级，x86 上 double 是硬件，板端是软浮点。 */
#include "vmap_render.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define W 240
#define H 320
#define NFEAT 600
#define REPS 200

static uint16_t buf[W * H];
static vmap_point_t pts[NFEAT][8];
static int pn[NFEAT];
static int pw[NFEAT];

static double now_ms(void)
{
    struct timespec ts;

    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec * 1000.0 + ts.tv_nsec / 1e6;
}

int main(void)
{
    vmap_canvas_t c;
    double t0;
    double t1;
    int r;
    int i;
    unsigned long drawn = 0;

    srand(12345);
    for (i = 0; i < NFEAT; i++) {
        int n = 2 + (rand() % 4);
        int k;
        int x = rand() % (W - 60);
        int y = rand() % (H - 60);

        for (k = 0; k < n; k++) {
            pts[i][k].x = x + k * 18 + (rand() % 5) - 2;
            pts[i][k].y = y + ((k & 1) ? 12 : 0) + (rand() % 5) - 2;
        }
        pn[i] = n;
        pw[i] = 1 + (rand() % 4);
    }

    memset(buf, 0, sizeof(buf));
    memset(&c, 0, sizeof(c));
    c.buf = buf;
    c.w = W;
    c.h = H;
    c.stride = W * 2;

    /* warmup */
    for (i = 0; i < NFEAT; i++) {
        vmap_render_stroke_ribbon(&c, pts[i], pn[i], pw[i], 0xffffu);
    }

    t0 = now_ms();
    for (r = 0; r < REPS; r++) {
        for (i = 0; i < NFEAT; i++) {
            vmap_render_stroke_ribbon(&c, pts[i], pn[i], pw[i], 0xffffu);
            drawn++;
        }
    }
    t1 = now_ms();
    printf("strips=%lu  %.2f ms total  %.1f ns/strip\n", drawn, t1 - t0,
        (t1 - t0) * 1e6 / (double)drawn);
    return 0;
}
